<template><div class="page-container"><div class="heading"><p>Academic opportunities</p><h1>Find your program</h1><span>Explore Colegio de Montalban's degree and certificate offerings.</span></div><div v-if="loading" class="state">Loading programs…</div><div v-else-if="error" class="state error">{{error}}</div><div v-else class="grid"><article v-for="course in courses" :key="course.id" class="card" :id="`program-${course.code}`"><img v-if="course.image_path" :src="imageUrl(course.image_path)" :alt="`${course.code} program poster`"><div class="body"><div class="meta"><b>{{course.code}}</b><span>{{course.duration}}</span></div><small>{{course.institute}}</small><h2>{{course.name}}</h2><p>{{course.description}}</p><details :open="route.query.program === course.code"><summary>Subjects and career paths</summary><h3>What you will study</h3><ul><li v-for="subject in course.subjects" :key="subject">{{subject}}</li></ul><h3>Career paths</h3><p>{{(course.career_paths||[]).join(' · ')}}</p></details></div></article></div></div></template>
<script setup>import{nextTick,onMounted,ref}from'vue';import api,{API_BASE}from'../utils/api';import { useRoute } from 'vue-router';const route=useRoute();const courses=ref([]),loading=ref(true),error=ref('');const imageUrl=path=>`${API_BASE}/api/storage/${path}`;onMounted(async()=>{try{courses.value=(await api.get('/courses')).data.courses}catch{error.value='Unable to load programs right now.'}finally{loading.value=false;await nextTick();if(route.query.program)document.getElementById(`program-${route.query.program}`)?.scrollIntoView({block:"center"})}})</script>
<style scoped>.page-container{max-width:1240px;margin:auto;padding:48px 28px 80px}.heading{text-align:center;max-width:720px;margin:0 auto 42px}.heading>p{color:#b18c12;font-weight:800;text-transform:uppercase;letter-spacing:.15em;font-size:11px}.heading h1{font:48px Georgia;color:#123f28;margin:10px}.heading span{color:#68756d}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.card{background:white;border:1px solid #e0e7e1;box-shadow:0 12px 30px rgba(20,63,40,.08);overflow:hidden}.card>img{width:100%;aspect-ratio:1;object-fit:cover;background:#e9efe9}.body{padding:24px}.meta{display:flex;justify-content:space-between;color:#17613a;font-size:12px;text-transform:uppercase}.body small{display:block;color:#a17f13;margin:12px 0 6px}.body h2{font:24px/1.2 Georgia;color:#143f28;margin:0 0 14px}.body>p{color:#68756d;font-size:13px;line-height:1.65;min-height:86px}.body details{border-top:1px solid #e1e6e2;padding-top:14px;color:#56645a;font-size:12px}.body summary{cursor:pointer;color:#17613a;font-weight:800}.body h3{font-size:12px;margin:14px 0 6px;color:#243e2e}.body ul{padding-left:18px;line-height:1.6}.state{text-align:center;padding:80px}.error{color:#b42318}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.grid{grid-template-columns:1fr}.page-container{padding:30px 16px}.heading h1{font-size:38px}}</style>
